        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        # The original program enters a broken prompt loop for malformed plugin
        # files.  For normal use we reproduce the visible first prompt and stop.
        print("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.")
        if invalid_prompt:
