    for item in data:
        if isinstance(item, dict):
            # Accept a few simple plugin description shapes.  This is enough for
            # runtime-created plugins while keeping built-ins independent.
            label = item.get("content_type") or item.get("type") or item.get("name") or item.get("plugin_name")
