        "thorough": False, "display": False, "suppress": False, "hide": False,
        "time_flag": False, "help": False, "version": False,
    }
    for f in EXTRACT_FLAGS:
        d[f] = False
    return d


def parse_args(argv):
    opts = default_opts()
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
