            break
        if arg.startswith("--") and len(arg) > 2:
            body = arg[2:]
            val = None
            if "=" in body:
                body, val = body.split("=", 1)
            if body in VALUE_LONG_NAMES:
                key, disp = VALUE_LONG_NAMES[body]
                if val is None:
