                        clap_error_missing(disp)
                    val = argv[i + 1]
                    i += 1
                opts[key] = val
            elif body in LONG_BOOL and val is None:
                opts[LONG_BOOL[body]] = True
            else:
                clap_error_unexpected(arg)
        elif arg.startswith("-") and arg != "-":
            cluster = arg[1:]
            j = 0
            while j < len(cluster):
                ch = cluster[j]
                if ch in SHORT_VALUE:
                    key, disp = SHORT_VALUE[ch]
                    if j + 1 < len(cluster):
                        opts[key] = cluster[j + 1:]
                        j = len(cluster)
                    else:
                        if i + 1 >= len(argv):
                            clap_error_missing(disp)
                        opts[key] = argv[i + 1]
                        i += 1
                        j = len(cluster)
                elif ch in SHORT_BOOL:
                    opts[SHORT_BOOL[ch]] = True
                    j += 1
                else:
                    clap_error_unexpected("-" + ch if len(cluster) == 1 else "-" + ch)
        else:
            clap_error_unexpected(arg)
        i += 1
    return opts


def regex_compile_user(pattern, which):
    if not pattern:
        return None
    try:
        return re.compile(pattern)
    except re.error as e:
        linecol = "595:54" if which == "drop" else "598:58"
        # A close facsimile of Rust regex unwrap panic.  The thread id in the
        # original is the process id on this platform.
        sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at src/main.rs:{linecol}:\n")
        sys.stderr.write("called `Result::unwrap()` on an `Err` value: Syntax(\n")
        sys.stderr.write("~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n")
        sys.stderr.write("regex parse error:\n")
        sys.stderr.write(f"    {pattern}\n")
        sys.stderr.write("    ^\n")
        msg = str(e)
        if "unterminated character set" in msg or "unclosed character" in msg:
            msg = "unclosed character class"
        sys.stderr.write(f"error: {msg}\n")
        sys.stderr.write("~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n")
        sys.stderr.write(")\n")
        sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
