def normalize_match(extractor, text):
    if extractor.strip_trailing_dot:
        return text.rstrip('.')
    return text


def pass_candidate(text, filter_re, drop_re):
    if filter_re is not None and filter_re.search(text) is None:
        return False
    if drop_re is not None and drop_re.search(text) is not None:
        return False
    return True


def format_text(label, data, line_no, filename, opts):
    if opts["display"]:
        if opts["line"]:
            if opts["hide"]:
                return f"file: {filename} {data}, line: {line_no}"
            return f"{label}, file: {filename} {data}, line: {line_no}"
        else:
            if opts["hide"]:
                return f"file: {filename} {data}"
            return f"{label}, file: {filename} {data}"
    if opts["line"]:
        if opts["hide"]:
            return f"{data}, line: {line_no}"
        return f"{label}, {data}, line: {line_no}"
    if opts["hide"]:
        return data
    return f"{label}: {data}"


def csv_header(opts):
    parts = []
    if not opts["hide"]:
        parts.append("content_type")
    if opts["display"]:
        parts.append("file")
    if opts["line"]:
        parts.append("line")
    parts.append("data")
    return ", ".join(parts)


def format_csv(label, data, line_no, filename, opts):
    parts = []
    if not opts["hide"]:
        parts.append(label)
    if opts["display"]:
        parts.append(filename)
    if opts["line"]:
        parts.append(str(line_no))
    parts.append(data)
    return ", ".join(parts)


class Outputter:
    def __init__(self, path, opts):
        self.path = path
        self.opts = opts
        self.csv = bool(path) and path.endswith(".csv")
        self.fh = None
        if path:
            self.fh = open(path, "a", encoding="utf-8")
            if self.csv:
                self.fh.write(csv_header(opts) + "\n")

    def write_result(self, label, data, line_no, filename):
        if self.fh:
            if self.csv:
                self.fh.write(format_csv(label, data, line_no, filename, self.opts) + "\n")
            else:
                self.fh.write(format_text(label, data, line_no, filename, self.opts) + "\n")
        else:
            print(format_text(label, data, line_no, filename, self.opts))

    def close(self):
        if self.fh:
            self.fh.close()


def emit_candidate(out, label, data, line_no, filename, opts, filter_re, drop_re):
    if pass_candidate(data, filter_re, drop_re):
        out.write_result(label, data, line_no, filename)
        return True
    return False


def process_line(line, line_no, filename, active_extractors, opts, filter_re, drop_re, out):
    for ex in active_extractors:
        matches = list(ex.regex.finditer(line))
        if not matches:
            continue
        if opts["thorough"]:
            for m in matches:
                match_text = normalize_match(ex, m.group(0))
                if opts["clean"]:
                    emit_candidate(out, ex.label, match_text, line_no, filename, opts, filter_re, drop_re)
                else:
                    emit_candidate(out, ex.label, line, line_no, filename, opts, filter_re, drop_re)
                    emit_candidate(out, ex.label, match_text, line_no, filename, opts, filter_re, drop_re)
            continue
        else:
            if opts["clean"]:
                for m in matches:
                    match_text = normalize_match(ex, m.group(0))
                    if emit_candidate(out, ex.label, match_text, line_no, filename, opts, filter_re, drop_re):
                        return
                return
            else:
                if emit_candidate(out, ex.label, line, line_no, filename, opts, filter_re, drop_re):
                    return
                # If the full line was excluded by a filter/drop expression, the
                # program falls back to the first matching clean value that passes.
                if filter_re is not None or drop_re is not None:
                    for m in matches:
                        match_text = normalize_match(ex, m.group(0))
                        if emit_candidate(out, ex.label, match_text, line_no, filename, opts, filter_re, drop_re):
                            return
                return


def read_file_lines(path):
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for idx, raw in enumerate(f, 1):
            yield idx, raw.rstrip("\n").rstrip("\r")


def walk_dir_depth_first(path):
    try:
        entries = list(os.scandir(path))
    except Exception:
        return
    dirs = sorted([e for e in entries if e.is_dir(follow_symlinks=False)], key=lambda e: e.name)
    files = sorted([e for e in entries if e.is_file(follow_symlinks=False)], key=lambda e: e.name)
    for d in dirs:
        yield from walk_dir_depth_first(d.path)
    for f in files:
        yield f.path


def handle_list(plugins):
    # Re-read like the original; with a missing file this produces a second warning.
    plugins2, _ = load_plugins(warn_missing=True)
    if not plugins2:
        print(f"No plugins found. Plugin File: {plugin_path()}")
        sys.exit(1)
    for p in plugins2:
        label = p.get("label") or ""
        url = p.get("url") or ""
        if url:
            print(f"{label}: {url}")
        else:
            print(label)
    sys.exit(0)


def handle_plugin_commands(opts, plugins):
    if opts["list"]:
        handle_list(plugins)
    if opts["add"]:
        val = opts["add"]
        if not (val.startswith("http://") or val.startswith("https://")):
            sys.stderr.write("[-] Error: Failed to parse plugins.json from the provided URL. Reason: builder error: relative URL without a base\n")
            sys.exit(1)
        sys.stderr.write("[-] Error: Failed to parse plugins.json from the provided URL. Reason: error sending request\n")
        sys.exit(1)
    if opts["remove"]:
        sys.exit(1)
    if opts["update"]:
        # Re-read like the original; with a missing file this produces a second warning.
        plugins2, _ = load_plugins(warn_missing=True)
        val = opts["update"]
        if val == "all":
            sys.exit(1)
        found = False
        for p in plugins2:
            if p.get("url") == val:
                found = True
        if not found:
            print(f"[-] Error: No existing plugin found with the given URL: {val}")
            sys.exit(1)
        sys.exit(1)


def main():
    start = time.time()
    plugins, _ = load_plugins(warn_missing=True)
    opts = parse_args(sys.argv[1:])

    if opts["help"]:
        print(HELP_TEXT, end="")
        return 0
    if opts["version"]:
        print(VERSION_LINE)
        return 0

    handle_plugin_commands(opts, plugins)

    drop_re = regex_compile_user(opts["drop"], "drop")
    filter_re = regex_compile_user(opts["filter"], "filter")

    all_extractors = build_extractors(plugins)
    any_extraction = any(opts[f] for f in EXTRACT_FLAGS)
    if any_extraction:
        flagset = {f for f in EXTRACT_FLAGS if opts[f]}
        active = [e for e in all_extractors if e.flag in flagset]
    else:
        active = all_extractors

    out = None
    try:
        out = Outputter(opts["output"], opts)
        if opts["file"]:
            if not os.path.exists(opts["file"]):
                if not opts["ignore"]:
                    print(f"[-] File not found: {opts['file']}")
                return 1
            # If a directory is passed as a file, attempting to read it on the
            # original may block on some systems.  Here we simply try and report
            # the OS error unless errors are ignored.
            try:
                for line_no, line in read_file_lines(opts["file"]):
                    process_line(line, line_no, opts["file"], active, opts, filter_re, drop_re, out)
            except Exception as e:
                if not opts["ignore"]:
                    # Most normal error cases in the original are terse and go to stdout.
                    print(f"[-] Error reading file: {e}")
                return 1
        elif opts["directory"]:
            if os.path.isdir(opts["directory"]):
                for fpath in walk_dir_depth_first(opts["directory"]):
                    try:
                        for line_no, line in read_file_lines(fpath):
                            process_line(line, line_no, fpath, active, opts, filter_re, drop_re, out)
                    except Exception as e:
                        if not opts["ignore"]:
                            print(f"[-] Error reading file: {fpath}")
            # Missing/non-directory directories are silently ignored.
        else:
            if not opts["suppress"]:
                print(STDIN_NOTICE)
            for line_no, raw in enumerate(sys.stdin, 1):
                line = raw.rstrip("\n").rstrip("\r")
                process_line(line, line_no, "", active, opts, filter_re, drop_re, out)
    finally:
        if out:
            out.close()

    if opts["time_flag"]:
        elapsed = int(time.time() - start)
        h = elapsed // 3600
        m = (elapsed % 3600) // 60
        s = elapsed % 60
        print(f"[*] Time elapsed: {h:02d}h:{m:02d}m:{s:02d}s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
